# Ajustes posteriores al diccionario: orden de palabras con «IA», plurales, textos que no cabían en
# el lienzo en español, máscara más alta para letras latinas y recuadros de las capturas regeneradas.
POST = {
  '"default":"AI Programar"': '"default":"Programar con IA"',
  '"default":"etapas 01"': '"default":"Etapa 01"', '"default":"etapas 02"': '"default":"Etapa 02"', '"default":"etapas 03"': '"default":"Etapa 03"',
  'AI, ¡hazme un sitio web!': 'IA, ¡hazme un sitio web!',
  '"default":"AIasistente"': '"default":"Asistente IA"',
  '"default":"línea"': '"default":" líneas"',
  '"default":"3000línea"': '"default":"3000 líneas"',
  'AI Por qué dice disparates con tanta seriedad': 'Por qué la IA dice disparates tan seria',
  'AI Programando en vivo': 'Programando con IA',
  '"default":"Duración exacta al cuadro"': '"default":"Exacta al cuadro"',
  'Cientos de miles de millones de parámetros': 'Miles de millones de parámetros',
  'Da un paso pequeño en sentido contrario, de tamaño': 'Da un paso corto en sentido contrario, de longitud',
  '.ln { display: block; overflow: hidden; padding: .04em 0 .16em; margin: -.04em 0 -.16em; }':
    '.ln { display: block; overflow: hidden; padding: .22em 0 .22em; margin: -.22em 0 -.22em; }   /* máscara más alta: las letras latinas con acento o descendentes no se recortan */',
  '"default":"[0.648, 0.245, 0.104, 0.105]"': '"default":"[0.635, 0.32, 0.11, 0.09]"',
  '"default":"[0.74, 0.22, 0.22, 0.11]"': '"default":"[0.745, 0.25, 0.105, 0.095]"',
}

P = {'）':')','（':'(','＝':' = ','＋':'+','；':'; ','，':', ','：':': ','、':', ','！':'!','？':'?'}
CJK = re.compile(r'[\u3000-\u303f\u4e00-\u9fff\uff00-\uffef]')

def main(src, out):
    if os.path.exists(out): shutil.rmtree(out)
    shutil.copytree(src, out)
    keys = sorted(D, key=len, reverse=True)
    for f in sorted(glob.glob(os.path.join(out, '*', '*'))):
        if os.path.isdir(f): continue
        try: s = open(f, encoding='utf-8').read()
        except Exception: continue
        o = s
        for k in keys: s = s.replace(k, D[k])
        if f.endswith('index.html'):
            head, sep, tail = s.partition('<script')
            for k, v in P.items(): head = head.replace(k, v)
            head = head.replace('lang="zh-CN"', 'lang="es-MX"')
            tail = re.sub(r'<!--(.*?)-->', lambda m: '<!--' + ''.join(P.get(c, c) for c in m.group(1)) + '-->', tail, flags=re.S)
            s = head + sep + tail
            for k, v in POST.items(): s = s.replace(k, v)
        if s != o: open(f, 'w', encoding='utf-8').write(s)
        left = sorted(set(CJK.findall(s)))
        if left and not f.endswith('LICENSES.md'): print('REVISAR', f, ''.join(left))

if __name__ == '__main__':
    if len(sys.argv) != 3: sys.exit(__doc__)
    main(sys.argv[1], sys.argv[2])
